+import events from './events.json' with {type: 'json'};
+
+const DEFAULT_PAGE_SIZE = 2;
+const MIN_PAGE_SIZE = 1;
+const MAX_PAGE_SIZE = 3;
+
+export async function listTools() {
+  return [
+    {
+      name: 'events_list',
+      description: 'List events a page at a time in source order.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          cursor: { type: 'string', description: 'Opaque pagination cursor returned by a previous call.' },
+          page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
+        },
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+function encodeCursor(offset) {
+  return Buffer.from(String(offset), 'utf8').toString('base64');
+}
+
+function decodeCursor(cursor) {
+  let decoded;
+  try {
+    decoded = Buffer.from(cursor, 'base64').toString('utf8');
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (!/^\d+$/.test(decoded)) throw new Error('Unknown cursor');
+  const offset = Number(decoded);
+  if (!Number.isSafeInteger(offset) || offset < 0 || offset > events.length) {
+    throw new Error('Unknown cursor');
+  }
+  return offset;
+}
+
+export async function callTool(name, args) {
+  if (name !== 'events_list') throw new Error('Unknown tool: ' + name);
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments');
+  }
+
+  let offset = 0;
+  let pageSize = DEFAULT_PAGE_SIZE;
+
+  for (const key of Object.keys(args)) {
+    if (key !== 'cursor' && key !== 'page_size') {
+      throw new Error('Unknown argument: ' + key);
+    }
+  }
+
+  if (args.cursor !== undefined) {
+    if (typeof args.cursor !== 'string') throw new Error('cursor must be a string');
+    offset = decodeCursor(args.cursor);
+  }
+
+  if (args.page_size !== undefined) {
+    if (!Number.isInteger(args.page_size) || args.page_size < MIN_PAGE_SIZE || args.page_size > MAX_PAGE_SIZE) {
+      throw new Error('page_size must be an integer from ' + MIN_PAGE_SIZE + ' to ' + MAX_PAGE_SIZE);
+    }
+    pageSize = args.page_size;
+  }
+
+  const slice = events.slice(offset, offset + pageSize);
+  const result = { events: slice };
+  if (offset + pageSize < events.length) {
+    result.next_cursor = encodeCursor(offset + pageSize);
+  }
+
+  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
+}
